#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long sum = 0;
    if (n > 1) {
        for (long i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                long d1 = i;
                long d2 = n / i;
                if (d1 != n) sum += d1;
                if (d2 != n && d2 != d1) sum += d2;
            }
        }
    }

    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }
    return 0;
}
